"""Best Book Award operations for Open Library."""

import logging

from openlibrary.core import db
from openlibrary.core.bookshelves import Bookshelves

logger = logging.getLogger(__name__)


class Bestbook(db.CommonExtras):
    TABLENAME = "bestbook"
    PRIMARY_KEY = ("username", "work_id")

    class AwardConditionsError(Exception):
        pass

    @classmethod
    def add(
        cls,
        username: str,
        work_id: str,
        topic: str,
        comment: str = "",
        edition_id: int | None = None,
    ) -> int | None:
        """
        Adds an award when conditions are met, otherwise raises Bestbook.AwardConditionsError.
        """
        # Check if the user has marked the work as "Already Read"
        if not Bookshelves.user_has_read_work(username, work_id):
            raise cls.AwardConditionsError(
                "Only books which have been marked as read may be given awards"
            )

        # Check for duplicate nomination by the same patron
        existing_awards = cls.get_awards(work_id=work_id, username=username)
        if existing_awards:
            raise cls.AwardConditionsError(
                f"User {username} has already nominated work {work_id}"
            )

        # Check for duplicate topic
        existing_topic_awards = cls.get_awards(topic=topic, username=username)
        if existing_topic_awards:
            raise cls.AwardConditionsError(
                f"User {username} has already used topic {topic} for a different work"
            )

        oldb = db.get_db()
        return oldb.insert(
            cls.TABLENAME,
            username=username,
            work_id=work_id,
            topic=topic,
            comment=comment,
            edition_id=edition_id,
        )

    @classmethod
    def remove(
        cls,
        username: str,
        work_id: str | None = None,
        topic: str | None = None,
    ) -> int:
        """
        Removes any award for the username where the work_id or topic matches.
        """
        oldb = db.get_db()
        where = "username=$username"
        vars_ = {'username': username}
        if work_id is not None:
            where += " AND work_id=$work_id"
            vars_['work_id'] = work_id
        if topic is not None:
            where += " AND topic=$topic"
            vars_['topic'] = topic
        return oldb.delete(cls.TABLENAME, where=where, vars=vars_)

    @classmethod
    def get_count(
        cls,
        work_id: str | None = None,
        username: str | None = None,
        topic: str | None = None,
    ) -> int:
        """
        Returns the count of best book awards matching the specified filters.
        """
        query, vars_ = cls.prepare_query(
            select="count(*)", work_id=work_id, username=username, topic=topic
        )
        oldb = db.get_db()
        result = oldb.query(query, vars=vars_)
        return result[0].count if result else 0

    @classmethod
    def get_awards(
        cls,
        work_id: str | None = None,
        username: str | None = None,
        topic: str | None = None,
    ) -> list:
        """
        Returns the list of best book awards matching the specified filters (any combination of work_id, username, topic).
        """
        query, vars_ = cls.prepare_query(
            select="*", work_id=work_id, username=username, topic=topic
        )
        oldb = db.get_db()
        return list(oldb.query(query, vars=vars_))

    @classmethod
    def get_leaderboard(cls) -> list[dict]:
        """
        Returns the leaderboard of best books, aggregated as work_id plus award count, ordered by count descending.
        """
        oldb = db.get_db()
        query = (
            "SELECT work_id, count(*) as award_count "
            "FROM bestbook GROUP BY work_id ORDER BY award_count DESC"
        )
        result = oldb.query(query)
        return [
            {'work_id': r['work_id'], 'award_count': r['award_count']}
            for r in result
        ]

    @classmethod
    def prepare_query(
        cls,
        select: str = "*",
        work_id: str | None = None,
        username: str | None = None,
        topic: str | None = None,
    ) -> tuple[str, dict]:
        """
        Builds the SQL query string and its bound variables for fetching awards matching the specified filters.
        """
        query = f"SELECT {select} FROM {cls.TABLENAME}"
        conditions = []
        vars_ = {}
        if work_id is not None:
            conditions.append("work_id=$work_id")
            vars_['work_id'] = work_id
        if username is not None:
            conditions.append("username=$username")
            vars_['username'] = username
        if topic is not None:
            conditions.append("topic=$topic")
            vars_['topic'] = topic
        if conditions:
            query += " WHERE " + " AND ".join(conditions)
        return query, vars_
