    const [hover, setHover] = useState(false);
    const { avatar, text, onClick, resourceId, type: resolvedType } = usePermalink({ url, type, room });

    if (!resolvedType || !text) {
        return null;
    }

    let pillClass;
    if (resolvedType === PillType.AtRoomMention) {
        pillClass = "mx_AtRoomPill";
    } else if (resolvedType === PillType.UserMention) {
        pillClass = "mx_UserPill";
    } else if (resolvedType === PillType.RoomMention || resolvedType === "space") {
        pillClass = resolvedType === "space" ? "mx_SpacePill" : "mx_RoomPill";
