    );

    if (inMessage && url) {
        return (
            <bdi>
                <a
                    className={classes}
                    href={href}
                    onClick={onClick}
                    onMouseOver={() => setHover(true)}
                    onMouseLeave={() => setHover(false)}
                >
                    {content}
                </a>
            </bdi>
        );
    } else {
