```tsx
import React, { ReactElement, useState, useEffect } from "react";
import { Room } from "matrix-js-sdk/src/models/room";
import { RoomMember } from "matrix-js-sdk/src/models/room-member";
import { logger } from "matrix-js-sdk/src/logger";
import { MatrixEvent } from "matrix-js-sdk/src/models/event";

import { MatrixClientPeg } from "../../MatrixClientPeg";
import { parsePermalink } from "../../utils/permalinks/Permalinks";
import { PillType } from "../../components/views/elements/Pill";
import { ButtonEvent } from "../../components/views/elements/AccessibleButton";
import RoomAvatar from "../../components/views/avatars/RoomAvatar";
import MemberAvatar from "../../components/views/avatars/MemberAvatar";
import dis from "../../dispatcher/dispatcher";
import { Action } from "../../dispatcher/actions";

export interface UsePermalinkArgs {
    url?: string;
    type?: PillType;
    room?: Room;
}

export interface UsePermalinkResult {
    avatar: ReactElement | null;
    text: string | null;
    onClick: ((e: ButtonEvent) => void) | null;
    resourceId: string | null;
    type: PillType | "space" | null;
}

export function usePermalink({ url, type, room }: UsePermalinkArgs): UsePermalinkResult {
    const [profileMember, setProfileMember] = useState<RoomMember | null>(null);

    let resourceId: string | null = null;
    let effectiveType: PillType | "space" | null = null;
    let member: RoomMember | null = null;
    let resolvedRoom: Room | null = null;

    if (type) {
        effectiveType = type;
    } else if (url) {
        const parts = parsePermalink(url);
        if (parts) {
            resourceId = parts.primaryEntityId;
            const sigil = parts.sigil;
            if (sigil === "@") {
                effectiveType = PillType.UserMention;
            } else if (sigil === "#" || sigil === "!") {
                effectiveType = PillType.RoomMention;
            }
        }
    }

    if (effectiveType === PillType.AtRoomMention) {
        resolvedRoom = room ?? null;
    } else if (effectiveType === PillType.UserMention) {
        if (resourceId) {
            const localMember = room?.getMember(resourceId);
            if (localMember) {
                member = localMember;
            } else {
                member = new RoomMember(null, resourceId);
            }
        }
    } else if (effectiveType === PillType.RoomMention) {
        if (resourceId) {
            const client = MatrixClientPeg.get();
            if (resourceId[0] === "#") {
                resolvedRoom = client
                    .getRooms()
                    .find((r) => r.getCanonicalAlias() === resourceId || r.getAltAliases().includes(resourceId));
            } else {
                resolvedRoom = client.getRoom(resourceId);
            }
            if (resolvedRoom?.isSpaceRoom()) {
                effectiveType = "space";
            }
        }
    }

    let avatar: ReactElement | null = null;
    let text: string | null = null;
    let onClick: ((e: ButtonEvent) => void) | null = null;

    const activeMember = profileMember || member;

    if (effectiveType === PillType.AtRoomMention && resolvedRoom) {
        text = "@room";
        avatar = <RoomAvatar room={resolvedRoom} width={16} height={16} aria-hidden="true" />;
    } else if (effectiveType === PillType.UserMention && activeMember) {
        text = activeMember.rawDisplayName || resourceId;
        avatar = (
            <MemberAvatar member={activeMember} width={16} height={16} aria-hidden="true" hideTitle />
        );
        onClick = (e: ButtonEvent) => {
            e.preventDefault();
            dis.dispatch({
                action: Action.ViewUser,
                member: activeMember,
            });
        };
    } else if ((effectiveType === PillType.RoomMention || effectiveType === "space") && resolvedRoom) {
        text = resolvedRoom.name || resourceId;
        avatar = <RoomAvatar room={resolvedRoom} width={16} height={16} aria-hidden="true" />;
    }

    const needsProfileLookup =
        effectiveType === PillType.UserMention && resourceId !== null && !room?.getMember(resourceId);

    useEffect(() => {
        if (needsProfileLookup) {
            const userId = resourceId;
            const member = new RoomMember(null, userId);
            MatrixClientPeg.get()
                .getProfileInfo(userId)
                .then((resp) => {
                    member.name = resp.displayname;
                    member.rawDisplayName = resp.displayname;
                    member.events.member = {
                        getContent: () => {
                            return { avatar_url: resp.avatar_url };
                        },
                        getDirectionalContent: function () {
                            return this.getContent();
                        },
                    } as MatrixEvent;
                    setProfileMember(member);
                })
                .catch((err) => {
                    logger.error("Could not retrieve profile data for " + userId + ":", err);
                });
        }
    }, [needsProfileLookup, resourceId]);

    return {
        avatar,
        text,
        onClick,
        resourceId,
        type: effectiveType,
    };
}
```

