    public static roomNotifLen(): number {
        return "@room".length;
    }

    public constructor(props: IProps) {
        super(props);

        this.state = {
            resourceId: null,
            pillType: null,
            member: null,
            room: null,
            hover: false,
        };
    }

    private load(): void {
        let resourceId: string;
        let prefix: string;

        if (this.props.url) {
            if (this.props.inMessage) {
                const parts = parsePermalink(this.props.url);
                resourceId = parts.primaryEntityId; // The room/user ID
                prefix = parts.sigil; // The first character of prefix
            } else {
                resourceId = getPrimaryPermalinkEntity(this.props.url);
                prefix = resourceId ? resourceId[0] : undefined;
            }
        }

        const pillType =
            this.props.type ||
            {
                "@": PillType.UserMention,
                "#": PillType.RoomMention,
                "!": PillType.RoomMention,
            }[prefix];

        let member: RoomMember;
        let room: Room;
        switch (pillType) {
            case PillType.AtRoomMention:
                {
                    room = this.props.room;
                }
                break;
            case PillType.UserMention:
                {
                    const localMember = this.props.room?.getMember(resourceId);
                    member = localMember;
                    if (!localMember) {
                        member = new RoomMember(null, resourceId);
                        this.doProfileLookup(resourceId, member);
                    }
                }
                break;
            case PillType.RoomMention:
                {
                    const localRoom =
                        resourceId[0] === "#"
                            ? MatrixClientPeg.get()
                                  .getRooms()
                                  .find((r) => {
                                      return (
                                          r.getCanonicalAlias() === resourceId || r.getAltAliases().includes(resourceId)
                                      );
                                  })
                            : MatrixClientPeg.get().getRoom(resourceId);
                    room = localRoom;
