/**
 * React functional component that renders a user, room, or @room mention "pill"
 * with an avatar and optional tooltip. Uses the usePermalink hook internally
 * and renders either an anchor (when inMessage) or span element.
 */
export function Pill({ type, url, inMessage, room, shouldShowPillAvatar }: IProps): JSX.Element | null {
    const [hover, setHover] = useState(false);
    const { avatar, text, onClick, resourceId, type: resolvedType } = usePermalink({ url, type, room });

    // Deliberately render nothing if the type cannot be detected
    if (!resolvedType || !text) {
        return null;
    }

    let pillClass: string;
    if (resolvedType === PillType.AtRoomMention) {
        pillClass = "mx_AtRoomPill";
    } else if (resolvedType === PillType.UserMention) {
        pillClass = "mx_UserPill";
    } else {
        // RoomMention or "space"
        pillClass = resolvedType === "space" ? "mx_SpacePill" : "mx_RoomPill";
    }

    const isCurrentUser = resolvedType === PillType.UserMention && resourceId === MatrixClientPeg.get().getUserId();
    const classes = classNames("mx_Pill", pillClass, {
        mx_UserPill_me: isCurrentUser,
    });

    const tip = hover && resourceId ? <Tooltip label={resourceId} alignment={Alignment.Right} /> : null;
    const avatarElement = shouldShowPillAvatar ? avatar : null;

    const content = (
        <>
            {avatarElement}
            <span className="mx_Pill_linkText">{text}</span>
            {tip}
